  2576      // write individual genotype information
  2577      kstring_t *str = &v->indiv;
  2578      int i;
  2579      if (v->n_sample > 0) {
  2580          for (i = 0; i < v->n_fmt; ++i) {
  2581              fmt_aux_t *z = &fmt[i];
