  2587                  bcf_enc_vint(str, (z->size>>2) * v->n_sample, (int32_t*)z->buf, z->size>>2);
  2588              } else {
  2589                  bcf_enc_size(str, z->size>>2, BCF_BT_FLOAT);
  2590                  if (serialize_float_array(str, (z->size>>2) * (size_t)v->n_sample,
  2591                                            (float *) z->buf) != 0) {
