   217  static int is_text_only(const unsigned char *u, const unsigned char *ulim)
   218  {
   219      for (; u < ulim; u++)
   220          if (! (*u >= ' ' || *u == '\t' || *u == '\r' || *u == '\n'))
   221              return 0;
   222
   223      return 1;
